// B33 — stamped by electron-vite (`define` in electron.vite.config.ts) when the main is built.

/** The commit the app was built from, or `null` when the build could not read it. */
declare const __DONEL_BUILD_COMMIT__: string | null;
/** When the main was built (epoch ms). */
declare const __DONEL_BUILT_AT__: number;
